int factorial(int n) {
    int i, j = 1;
    for (i = 1; i <= n; i++) j *= i;
    return j;
}

int factorial(int n) {
    int j = 1;
    int i = 1; /* initialization */
    while (i <= n /* condition */) {
        j *= i;
        i++; /* increment */
    }
    return j;
}

